// apps/shared/constants/cookies.ts

/**
 * Name of the authentication token cookie.
 * Used for storing the JWT in the browser/server.
 */
export const COOKIE_NAME = "billai-token";

/**
 * Default cookie options to use whenever setting/removing the auth cookie.
 * You can use these with libraries like js-cookie or Next.js cookies.
 */
export const COOKIE_OPTIONS = {
  // Cookie path; '/' makes it available across the entire site
  path: "/",
  // Secure cookies should only be sent over HTTPS (set to true in production)
  secure: process.env.NODE_ENV === "production",
  // Only accessible via HTTP(S), not JavaScript (helps prevent XSS)
  httpOnly: true,
  // Cookie expiration in days
  expires: 7,
  // Optional: SameSite setting for CSRF protection
  sameSite: "lax" as const,
};

/**
 * Helper function to get the auth cookie name
 */
export const getAuthCookieName = () => COOKIE_NAME;
