// shared/schemas/integration.schema.ts
import { z } from "zod";
import { AppReferenceSchema } from "./app.schema";

/**
 * Base Integration schema — defines core structure.
 */
export const IntegrationBaseSchema = z.object({
  id: z.uuid(),
  appId: z.uuid(),
  type: z.string(),
  config: z.any(),
  createdAt: z.date(),
});

/**
 * Reference schema — lightweight version for embedding in other models.
 */
export const IntegrationReferenceSchema = IntegrationBaseSchema.pick({
  id: true,
  type: true,
});

/**
 * Detailed schema — includes relations.
 */
export const IntegrationDetailedSchema = IntegrationBaseSchema.extend({
  app: z.lazy(() => AppReferenceSchema),
});

export type IntegrationBase = z.infer<typeof IntegrationBaseSchema>;
export type IntegrationReference = z.infer<typeof IntegrationReferenceSchema>;
export type IntegrationDetailed = z.infer<typeof IntegrationDetailedSchema>;
