// shared/schemas/globalAllowedOrigin.schema.ts
import { z } from "zod";

/**
 * Represents a globally allowed CORS origin for the Bill AI platform.
 * These origins apply across all organizations and apps.
 */
export const GlobalAllowedOriginSchema = z.object({
  id: z.uuid(),
  origin: z.url().or(z.string().regex(/^https?:\/\/[a-zA-Z0-9.-]+(:[0-9]+)?$/)), // allow localhost or custom domains
  createdAt: z.date(),
});

/**
 * A more detailed version used internally with computed or relational data.
 */
export const GlobalAllowedOriginDetailedSchema =
  GlobalAllowedOriginSchema.extend({
    referencedBy: z
      .array(
        z.object({
          organizationId: z.uuid().nullable(),
          organizationName: z.string().nullable(),
        })
      )
      .optional(),
  });

export type GlobalAllowedOrigin = z.infer<typeof GlobalAllowedOriginSchema>;
export type GlobalAllowedOriginDetailed = z.infer<
  typeof GlobalAllowedOriginDetailedSchema
>;
