// apps/shared/schemas/auth.schema.ts
import { z } from "zod";
import { UserDetailedSchema } from "./user.schema";

/** Auth response */
export const AuthResponseSchema = z.object({
  user: z.lazy(() => UserDetailedSchema),
  token: z.string(),
});

// ─────────────────────────────────────────────
// Input Schemas
// ─────────────────────────────────────────────
/** Input schema for user registration */
export const UserRegisterInputSchema = z.object({
  email: z.email(),
  password: z.string(),
  name: z.string().optional(),
  origin: z.string().optional(),
  organizationId: z.uuid().optional(),
});

/** Input schema for user registration */
export const UserLoginInputSchema = z.object({
  email: z.email(),
  password: z.string(),
  origin: z.string().optional(),
  organizationId: z.uuid().optional(),
});

// ─────────────────────────────────────────────
// Verified Token Result Schema
// ─────────────────────────────────────────────
/** Schema for the result of a verified JWT token */
export const VerifiedTokenResultSchema = z.object({
  userId: z.string(),
  organizationId: z.string().nullable(),
  planId: z.string().nullable(),
  exp: z.number().optional(),
});

export type VerifiedTokenResult = z.infer<typeof VerifiedTokenResultSchema>;
export type UserRegisterInput = z.infer<typeof UserRegisterInputSchema>;
export type UserLoginInput = z.infer<typeof UserLoginInputSchema>;
export type AuthResponse = z.infer<typeof AuthResponseSchema>;
