// apps/shared/schemas/usage.schema.ts
import { z } from "zod";
// import { FeatureSchema } from "./feature.schema"; // assuming you have a Feature enum/schema
import { FeatureEnum, UsageLogReferenceSchema } from "./usageLog.schema"; // your UsageLog schema
import { UserReferenceSchema } from "./user.schema"; // your User schema

// ------------------------------
// Base Schemas
// ------------------------------

// Represents usage by feature
export const UsageByFeatureSchema = z.object({
  feature: FeatureEnum,
  usage: z.number(),
});

export const MonthlyUsageSchema = z.object({
  month: z.string(), // e.g., "2025-10"
  usage: z.number(),
  totalCost: z.number().optional(),
  breakdown: z.record(z.string(), z.number()).optional(),
  logs: z.array(UsageLogReferenceSchema).optional(),
});

export const UsageSummarySchema = z.object({
  currentUsage: z.number(),
  usageLimit: z.number().optional(),
  periodStart: z.string(),
  periodEnd: z.string(),
  isOverLimit: z.boolean(),
  history: z.array(MonthlyUsageSchema).optional(),
  estimatedCost: z.number().optional(),
});

export const UsageSummaryChartSchema = z.object({
  totalUsage: z.number(),
  currentMonthUsage: z.number(),
  monthlyHistory: z.array(MonthlyUsageSchema),
  byFeature: z.array(UsageByFeatureSchema),
  planLimit: z.number().optional(),
  percentUsed: z.number().optional(),
});

// ------------------------------
// Input Schemas
// ------------------------------
export const RecordUsageInputSchema = z.object({
  userId: z.number(),
  feature: FeatureEnum,
  usage: z.number(),
  sessionId: z.string().optional(),
  unitCost: z.number().optional(),
  organizationId: z.number().optional(),
  metadata: z.record(z.string(), z.any()).optional(),
  billed: z.boolean().optional(),
  timestamp: z.preprocess(
    (arg) => (arg ? new Date(arg as string) : undefined),
    z.date().optional()
  ),
});

// ------------------------------
// Alerts and Table Schemas
// ------------------------------
export const UsageThresholdAlertSchema = z.object({
  userId: z.number(),
  used: z.number(),
  max: z.number(),
});

export const UsageLogWithUserSchema = UsageLogReferenceSchema.extend({
  user: UserReferenceSchema.optional(),
});

export const UsageLogsTableSchema = z.object({
  logs: z.array(UsageLogWithUserSchema),
  totalCount: z.number(),
});

export const UsageSummaryItemSchema = z.object({
  feature: FeatureEnum,
  totalUsage: z.number(),
});

export const OrgUsageSummaryItemSchema = z.object({
  feature: FeatureEnum,
  _sum: z.object({
    usage: z.number().nullable(),
  }),
});

export const OrgUsageSummarySchema = z.array(OrgUsageSummaryItemSchema);

// ------------------------------
// TypeScript types (add these if not already present)
// ------------------------------

/** Type for usage summary per feature */
export type FeatureUsageSummary = {
  feature: string;
  totalUsage: number;
};

/** Type for usage per month */
export type MonthlyUsage = {
  month: string;
  usage: number;
};

/** Type for the returned data from getUsageForDateRange */
export type UsageForDateRangeResult = {
  logs: UsageLogWithUser[];
  totalCount: number;
  summary: FeatureUsageSummary[];
  monthly: MonthlyUsage[];
};

// ------------------------------
// Type exports (inferred from Zod)
// ------------------------------
export type RecordUsageInput = z.infer<typeof RecordUsageInputSchema>;
export type UsageByFeature = z.infer<typeof UsageByFeatureSchema>;
export type UsageSummary = z.infer<typeof UsageSummarySchema>;
export type UsageSummaryChart = z.infer<typeof UsageSummaryChartSchema>;
export type UsageThresholdAlert = z.infer<typeof UsageThresholdAlertSchema>;
export type UsageLogWithUser = z.infer<typeof UsageLogWithUserSchema>;
export type UsageLogsTable = z.infer<typeof UsageLogsTableSchema>;
export type UsageSummaryItem = z.infer<typeof UsageSummaryItemSchema>;
export type OrgUsageSummaryItem = z.infer<typeof OrgUsageSummaryItemSchema>;
export type OrgUsageSummary = z.infer<typeof OrgUsageSummarySchema>;
