// shared/schemas/forecast.schema.ts
import { z } from "zod";
import { AppReferenceSchema } from "./app.schema";

/**
 * Base Forecast schema — defines core structure.
 */
export const ForecastBaseSchema = z.object({
  id: z.uuid(),
  appId: z.uuid(),
  metric: z.string(),
  predicted: z.number(),
  startDate: z.date(),
  endDate: z.date(),
  createdAt: z.date(),
});

/**
 * Reference schema — lightweight version for embedding in other models.
 */
export const ForecastReferenceSchema = ForecastBaseSchema.pick({
  id: true,
  metric: true,
  predicted: true,
  startDate: true,
  endDate: true,
});

/**
 * Detailed schema — includes relations.
 */
export const ForecastDetailedSchema = ForecastBaseSchema.extend({
  app: z.lazy(() => AppReferenceSchema),
});

export type ForecastBase = z.infer<typeof ForecastBaseSchema>;
export type ForecastReference = z.infer<typeof ForecastReferenceSchema>;
export type ForecastDetailed = z.infer<typeof ForecastDetailedSchema>;
