// shared/schemas/usagePricing.schema.ts
import { z } from "zod";
import { AppReferenceSchema } from "./app.schema";

/**
 * Base schema — defines the core fields for usage-based pricing
 */
export const UsagePricingBaseSchema = z.object({
  id: z.uuid(),
  appId: z.uuid(),
  metric: z.string(),
  pricePerUnit: z.number(),
  currency: z.string().default("usd"),
  unitName: z.string().optional(), // e.g., "tokens", "requests"
  billingCycle: z.enum(["monthly", "yearly"]).default("monthly"),
  tiered: z.boolean().optional(), // future support for tiered pricing
  metadata: z.record(z.string(), z.any()).optional(),
  createdAt: z.date(),
  updatedAt: z.date().optional(),
});

/**
 * Reference schema — minimal fields for lightweight embedding
 */
export const UsagePricingReferenceSchema = UsagePricingBaseSchema.pick({
  id: true,
  metric: true,
  pricePerUnit: true,
  currency: true,
  unitName: true,
});

/**
 * Detailed schema — includes relations for full context
 */
export const UsagePricingDetailedSchema = UsagePricingBaseSchema.extend({
  app: z.lazy(() => AppReferenceSchema),
});

// Types
export type UsagePricingBase = z.infer<typeof UsagePricingBaseSchema>;
export type UsagePricingReference = z.infer<typeof UsagePricingReferenceSchema>;
export type UsagePricingDetailed = z.infer<typeof UsagePricingDetailedSchema>;
