// shared/schemas/featureFlag.schema.ts
import { z } from "zod";
import { AppReferenceSchema } from "./app.schema";

/**
 * Base FeatureFlag schema — defines the core data structure.
 */
export const FeatureFlagBaseSchema = z.object({
  id: z.uuid(),
  name: z.string(),
  description: z.string().optional(),
  isActive: z.boolean(),
  createdAt: z.date(),
  updatedAt: z.date(),
  appId: z.uuid().optional(),
});

/**
 * Reference schema — lightweight version for embedding.
 */
export const FeatureFlagReferenceSchema = FeatureFlagBaseSchema.pick({
  id: true,
  name: true,
  isActive: true,
  appId: true,
});

/**
 * Detailed schema — includes full relations.
 */
export const FeatureFlagDetailedSchema = FeatureFlagBaseSchema.extend({
  app: z.lazy(() => AppReferenceSchema).optional(),
});

export type FeatureFlagBase = z.infer<typeof FeatureFlagBaseSchema>;
export type FeatureFlagReference = z.infer<typeof FeatureFlagReferenceSchema>;
export type FeatureFlagDetailed = z.infer<typeof FeatureFlagDetailedSchema>;
