// apps/shared/schemas/openmeter.shema.ts
import { z } from "zod";
/**
 * Minimal schema for sending usage to OpenMeter.
 * Only includes fields needed for feature-level tracking.
 */
export const OpenMeterUsageEntrySchema = z.object({
  userId: z.uuid(),
  feature: z.string(), // Could also use FeatureEnum
  usage: z.number().nonnegative(),
  organizationId: z.uuid().optional(),
  apiKeyId: z.uuid().optional(),
  sessionId: z.uuid().optional(),
  createdAt: z.date().optional(),
  metadata: z.record(z.string(), z.any()).optional(),
});

export type OpenMeterUsageEntry = z.infer<typeof OpenMeterUsageEntrySchema>;
